def transform(grid):
    out = [row[:] for row in grid]
    for i, row in enumerate(grid):
        for j, value in enumerate(row):
            if value != 2: continue
            neighbors = ((i-1,j),(i+1,j),(i,j-1),(i,j+1))
            count = sum(0 <= a < len(grid) and 0 <= b < len(row) and grid[a][b] == 3 for a,b in neighbors)
            if count >= 2:
                for a in range(max(0,i-1), min(len(grid),i+2)):
                    for b in range(max(0,j-1), min(len(row),j+2)):
                        if grid[a][b] != 2: out[a][b] = 1
    return out
